"""Render ``tests/contract/routes.md`` from the live route table (``just routes``)."""

from __future__ import annotations

import os
from pathlib import Path

from tests.contract.route_inventory import RouteInfo, collect_routes

ROUTES_MD = Path(__file__).with_name("routes.md")
_HEADER = (
    "# Route inventory\n\n"
    "Generated by `just routes` (T-UT03); do not edit. Kind: page, fragment (HTMX/overlay), "
    "action (state change or download).\n\n"
    "| Method | Path | Router | Handler | Kind | Auth |\n|---|---|---|---|---|---|\n"
)


def render(routes: tuple[RouteInfo, ...]) -> str:
    rows = sorted(routes, key=lambda r: (r.router, r.path, r.method))
    body = "".join(
        f"| {r.method} | `{r.path}` | {r.router} | {r.handler} | {r.kind} | {r.auth} |\n"
        for r in rows
    )
    return _HEADER + body


def main() -> None:
    os.environ.setdefault("BUDGET_ENV", "test")
    from budget_planner.web.app import create_app  # noqa: PLC0415

    ROUTES_MD.write_text(render(collect_routes(create_app())), encoding="utf-8")


if __name__ == "__main__":
    main()
